<?php
/** Reviewed school governance workflows and declarative, read-only integrations. */
if(!defined('SCHOOLOS_INSIGHTS_LIBRARY')){header('Location: index.php?s=intelligence&area=governance');exit;}
function gv_schema():array{$ddl=[];foreach(['alumni','mentoring','funds','donations','scholarships','applications','evidence','deadlines','processing','requests','policies'] as $name)$ddl[]="CREATE TABLE IF NOT EXISTS gv_$name(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,payload_json MEDIUMTEXT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,reviewed_by BIGINT UNSIGNED NULL,review_note VARCHAR(1000) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY(tenant_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4";return array_merge($ddl,[
"CREATE TABLE IF NOT EXISTS gv_bank_receipts(tenant_id BIGINT UNSIGNED NOT NULL,reference VARCHAR(100) NOT NULL,donation_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(tenant_id,reference)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS gv_groups(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,created_by BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS gv_members(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,group_id BIGINT UNSIGNED NOT NULL,tenant_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'invited',shares_json TEXT NOT NULL,approved_by BIGINT UNSIGNED NULL,UNIQUE KEY(group_id,tenant_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS gv_group_users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,group_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,UNIQUE KEY(group_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS gv_adoptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,policy_id BIGINT UNSIGNED NOT NULL,reviewed_by BIGINT UNSIGNED NOT NULL,note VARCHAR(1000) NOT NULL,UNIQUE KEY(tenant_id,policy_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS gv_plugins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,version VARCHAR(40) NOT NULL,api_version INT NOT NULL DEFAULT 1,scopes_json TEXT NOT NULL,endpoint TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS gv_api_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,plugin_id BIGINT UNSIGNED NOT NULL,owner_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,active TINYINT NOT NULL DEFAULT 1,UNIQUE KEY(token_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS gv_api_usage(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,token_id BIGINT UNSIGNED NOT NULL,bucket VARCHAR(20) NOT NULL,requests INT NOT NULL,UNIQUE KEY(token_id,bucket)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
]);}
function gv_cap(string $kind):string{return match($kind){'alumni','mentoring','funds','donations','scholarships','applications'=>'alumni_manager','processing','requests'=>'privacy_officer','policies'=>'group_analyst',default=>'accreditation_manager'};}
function gv_insert(array $u,string $kind,string $title,array $payload,string $status='draft'):int{if(!in_array($kind,['alumni','mentoring','funds','donations','scholarships','applications','evidence','deadlines','processing','requests','policies'],true))throw new LogicException('Invalid workflow.');q("INSERT INTO gv_$kind(tenant_id,title,payload_json,status,created_by) VALUES(?,?,?,?,?)",[$u['tenant_id'],$title,json_encode($payload,JSON_THROW_ON_ERROR),$status,$u['id']]);return (int)$GLOBALS['pdo']->lastInsertId();}
function gv_review(array $u,string $kind,int $id,string $decision,string $note):string{ix_need($u,gv_cap($kind));return sv_tx(function()use($u,$kind,$id,$decision,$note){$r=ix_own('gv_'.$kind,$u,$id,true);if(!in_array($r['status'],['draft','pending'],true)||(int)$r['created_by']===(int)$u['id'])throw new RuntimeException('A different authorized reviewer must review this pending record.');if(!in_array($decision,['approved','rejected'],true))throw new RuntimeException('Invalid review decision.');$p=json_decode($r['payload_json'],true);if($decision==='approved'){
 if($kind==='mentoring'){$supervisor=ix_fresh((int)$u['tenant_id'],op_id('supervisor_id'));if(!in_array($supervisor['role'],['teacher','staff','school_admin'],true))throw new RuntimeException('An active school employee must supervise mentoring.');$alumni=ix_own('gv_alumni',$u,(int)$p['alumni_id']);if($alumni['status']!=='approved')throw new RuntimeException('Alumnus is not approved.');$p['supervisor_id']=(int)$supervisor['id'];}
 if($kind==='applications'){$round=ix_own('gv_scholarships',$u,(int)$p['round_id'],true);$rp=json_decode($round['payload_json'],true);if($round['status']!=='approved')throw new RuntimeException('Scholarship round not approved.');$used=0;foreach(q("SELECT payload_json FROM gv_applications WHERE tenant_id=? AND status IN ('approved','applied')",[$u['tenant_id']])->fetchAll() as $app){$ap=json_decode($app['payload_json'],true);if((int)$ap['round_id']===(int)$round['id'])$used+=(int)$ap['amount_kobo'];}if($used+(int)$p['amount_kobo']>(int)$rp['budget_kobo'])throw new RuntimeException('Scholarship budget exceeded.');}
 if($kind==='donations'){ix_need($u,'finance_reports');$fund=ix_own('gv_funds',$u,(int)$p['fund_id']);if($fund['status']!=='approved')throw new RuntimeException('Fundraising purpose not approved.');$ref=ix_key(op_text('bank_reference',100,true));foreach(q("SELECT payload_json FROM gv_donations WHERE tenant_id=? AND status='approved'",[$u['tenant_id']])->fetchAll() as $other)if((json_decode($other['payload_json'],true)['bank_reference']??'')===$ref)throw new RuntimeException('Bank receipt reference already used.');q('INSERT INTO gv_bank_receipts VALUES(?,?,?)',[$u['tenant_id'],$ref,$r['id']]);$p['bank_reference']=$ref;fnJournal((int)$u['tenant_id'],'DON-'.$r['id'],'1000','2130',(int)$p['amount_kobo'],'School','Reviewed restricted fundraising receipt');}
 }q("UPDATE gv_$kind SET status=?,reviewed_by=?,review_note=?,payload_json=? WHERE tenant_id=? AND id=?",[$decision,$u['id'],$note,json_encode($p),$u['tenant_id'],$id]);audit('governance.review',$kind,(string)$id);return 'Independent review recorded.';});}
function gv_scopes(string $json):array{$v=json_decode($json,true,16,JSON_THROW_ON_ERROR);$allowed=['executive','enrolment','attendance','academics','operations','finance'];if(!is_array($v)||!array_is_list($v)||!$v||count($v)>6||array_diff($v,$allowed)||count(array_unique($v))!==count($v))throw new RuntimeException('Use unique allowlisted aggregate dataset names.');return $v;}
function gv_group_access(array $u,int $id):array{ix_need($u,'group_analyst');$group=q('SELECT * FROM gv_groups WHERE id=?',[$id])->fetch();$own=$group&&$u['role']==='school_admin';$member=q("SELECT * FROM gv_members WHERE group_id=? AND tenant_id=? AND status='approved'",[$id,$u['tenant_id']])->fetch();if(!$group||!$member||(!$own&&!g('SELECT id FROM gv_group_users WHERE group_id=? AND tenant_id=? AND user_id=?',[$id,$u['tenant_id'],$u['id']])))throw new RuntimeException('An explicit active school-group grant and school consent are required.');return $group;}
function gv_group_report(array $u,int $id,string $dataset,array $filters):array{$group=gv_group_access($u,$id);if(!in_array($dataset,gv_scopes('["executive","enrolment","attendance","academics","operations","finance"]'),true))throw new RuntimeException('Group dataset not available.');if($dataset==='finance')ix_need($u,'finance_reports');$rows=[];foreach(q("SELECT m.*,t.name FROM gv_members m JOIN tenants t ON t.id=m.tenant_id WHERE m.group_id=? AND m.status='approved'",[$id])->fetchAll() as $m){if(!in_array($dataset,json_decode($m['shares_json'],true),true))continue;$approver=ix_fresh((int)$m['tenant_id'],(int)$m['approved_by']);if($approver['role']!=='school_admin')continue;/* Consent gates fixed aggregates; no inherited access to individual records. */foreach(rp_data((int)$m['tenant_id'],$dataset,$filters) as $r)$rows[]=array_merge(['school'=>$m['name']],$r);}return $rows;}
function gv_api(string $token,string $dataset,array $filters):array{if(!preg_match('/^[a-f0-9]{64}$/D',$token))throw new RuntimeException('Invalid integration credential.');$t=q('SELECT * FROM gv_api_tokens WHERE token_hash=? AND active=1 AND expires_at>NOW()',[hash('sha256',$token)])->fetch();if(!$t)throw new RuntimeException('Integration credential expired or revoked.');$u=ix_fresh((int)$t['tenant_id'],(int)$t['owner_id']);ix_need($u,'integration_manager');$p=ix_own('gv_plugins',$u,(int)$t['plugin_id']);if($p['status']!=='approved'||(int)$p['api_version']!==1||!in_array($dataset,json_decode($p['scopes_json'],true),true))throw new RuntimeException('Integration scope denied.');ix_need(ix_fresh((int)$u['tenant_id'],(int)$p['approved_by']),'integration_manager');rp_require($u,$dataset);sv_tx(function()use($t){$bucket=date('Y-m-d H:i');q('INSERT INTO gv_api_usage(tenant_id,token_id,bucket,requests) VALUES(?,?,?,0) ON DUPLICATE KEY UPDATE requests=requests',[$t['tenant_id'],$t['id'],$bucket]);$n=(int)g('SELECT requests FROM gv_api_usage WHERE token_id=? AND bucket=? FOR UPDATE',[$t['id'],$bucket]);if($n>=60)throw new RuntimeException('Integration rate limit exceeded.');q('UPDATE gv_api_usage SET requests=requests+1 WHERE token_id=? AND bucket=?',[$t['id'],$bucket]);});return ['api_version'=>1,'dataset'=>$dataset,'filters'=>$filters,'rows'=>rp_report($u,$dataset,$filters),'classification'=>'Private school aggregates; do not redistribute.'];}
function gv_evidence_download(array $u,int $id):void{ix_need($u,'accreditation_manager');$r=ix_own('gv_evidence',$u,$id);$p=json_decode($r['payload_json'],true);if(empty($p['file_base64']))throw new RuntimeException('No evidence file attached.');header('Content-Type: '.$p['mime']);header('Content-Disposition: attachment; filename="evidence-'.$id.'.'.($p['mime']==='application/pdf'?'pdf':($p['mime']==='image/png'?'png':'jpg')).'"');header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');header('Content-Security-Policy: sandbox');header('Referrer-Policy: no-referrer');echo base64_decode($p['file_base64'],true);exit;}
function gv_rights_data(array $u,int $id):array{$r=ix_own('gv_requests',$u,$id);if((int)$r['created_by']!==(int)$u['id']||$r['status']!=='approved')throw new RuntimeException('Only the verified requester can retrieve an approved access response.');$p=json_decode($r['payload_json'],true);if($p['type']!=='access'||empty($p['identity_verified']))throw new RuntimeException('Identity-verified access request required.');$sid=(int)$p['student_id'];$data=['account'=>['name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']]];if($sid){$s=op_child($u,$sid);$data['student']=['name'=>$s['name'],'student_no'=>$s['student_no']];$data['attendance']=q('SELECT attendance_date,status FROM attendance WHERE tenant_id=? AND student_id=? ORDER BY attendance_date DESC LIMIT 366',[$u['tenant_id'],$sid])->fetchAll();$data['invoices']=q('SELECT reference,description,amount_kobo,discount_kobo,paid_kobo,status FROM fn_invoices WHERE tenant_id=? AND student_id=? ORDER BY id DESC LIMIT 100',[$u['tenant_id'],$sid])->fetchAll();}$data['scope']='Bounded account, linked-child attendance and invoices. Other records require the school data protection officer’s reviewed response; no automatic deletion.';return $data;}
function gv_action(array $u,string $a):string{$tid=(int)$u['tenant_id'];$uid=(int)$u['id'];
if($a==='review'){return gv_review($u,sv_enum('kind',['alumni','mentoring','funds','donations','scholarships','applications','evidence','processing','policies']),op_id('record_id'),sv_enum('decision',['approved','rejected']),op_text('review_note',1000,true));}
if($a==='alumni'){ix_need($u,'alumni_manager');if(op_text('adult_consent',10)!=='yes')throw new RuntimeException('Record adult alumnus consent before creating a profile.');gv_insert($u,'alumni',op_text('name',180,true),['year'=>op_text('year',20,true),'profession'=>op_text('profession',150,true),'mentoring_topics'=>op_text('topics',500,true),'adult_consent'=>true]);return 'Consented adult profile awaiting independent school verification.';}
if($a==='mentoring'){if(!in_array($u['role'],['parent','student'],true))throw new RuntimeException('Linked family account required.');$sid=op_id('student_id');op_child($u,$sid);$al=ix_own('gv_alumni',$u,op_id('alumni_id'));if($al['status']!=='approved')throw new RuntimeException('Select a verified adult alumnus.');gv_insert($u,'mentoring','Mentoring request',['student_id'=>$sid,'alumni_id'=>(int)$al['id'],'topic'=>op_text('topic',500,true)],'pending');return 'Mentoring requested; an employee supervisor and human approval are required. No private adult-child messaging was opened.';}
if($a==='fund'||$a==='scholarship'){ix_need($u,'alumni_manager');$from=op_date(op_text('starts_on',10,true));$to=op_date(op_text('ends_on',10,true));if($to<$from)throw new RuntimeException('Invalid application window.');$budget=op_money(op_text('budget',20,true));if($budget<=0)throw new RuntimeException('Positive goal/budget required.');gv_insert($u,$a==='fund'?'funds':'scholarships',op_text('title',180,true),['starts_on'=>$from,'ends_on'=>$to,'budget_kobo'=>$budget,'criteria'=>op_text('criteria',2000,true)]);return 'Purpose and budget submitted for independent approval.';}
if($a==='donation'){$fund=ix_own('gv_funds',$u,op_id('fund_id'));$p=json_decode($fund['payload_json'],true);if($fund['status']!=='approved'||date('Y-m-d')<$p['starts_on']||date('Y-m-d')>$p['ends_on'])throw new RuntimeException('Fundraising window not open.');$amount=op_money(op_text('amount',20,true));if($amount<=0)throw new RuntimeException('Positive amount required.');gv_insert($u,'donations','Bank donation awaiting verification',['fund_id'=>(int)$fund['id'],'amount_kobo'=>$amount,'donor_note'=>op_text('note',500)],'pending');return 'Donation declaration recorded. No cash or receipt is recognized until a different authorized reviewer verifies the bank receipt.';}
if($a==='application'){if(!in_array($u['role'],['parent','student'],true))throw new RuntimeException('Linked family applicant required.');$sid=op_id('student_id');op_child($u,$sid);$round=ix_own('gv_scholarships',$u,op_id('round_id'));$p=json_decode($round['payload_json'],true);if($round['status']!=='approved'||date('Y-m-d')<$p['starts_on']||date('Y-m-d')>$p['ends_on'])throw new RuntimeException('Scholarship application window closed.');$amount=op_money(op_text('amount',20,true));if($amount<=0||$amount>(int)$p['budget_kobo'])throw new RuntimeException('Invalid requested award.');gv_insert($u,'applications','Scholarship request',['student_id'=>$sid,'round_id'=>(int)$round['id'],'amount_kobo'=>$amount,'reason'=>op_text('reason',2000,true)],'pending');return 'Scholarship application submitted for budget-controlled review.';}
if($a==='award'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');return sv_tx(function()use($u,$tid,$uid){$app=ix_own('gv_applications',$u,op_id('application_id'),true);if($app['status']==='applied')return 'Award already applied.';if($app['status']!=='approved'||(int)$app['created_by']===$uid)throw new RuntimeException('An independently approved scholarship is required.');ix_need(ix_fresh($tid,(int)$app['reviewed_by']),'alumni_manager');$p=json_decode($app['payload_json'],true);$inv=sv_own('fn_invoices',$u,op_id('invoice_id'),true);$amount=(int)$p['amount_kobo'];$due=(int)$inv['amount_kobo']-(int)$inv['discount_kobo']+(int)$inv['penalty_kobo']-(int)$inv['paid_kobo'];if((int)$inv['student_id']!==(int)$p['student_id']||$amount>$due||$amount>(int)$inv['amount_kobo']-(int)$inv['discount_kobo'])throw new RuntimeException('Award must fit the linked student’s unallocated base fee balance.');q('UPDATE fn_invoices SET discount_kobo=discount_kobo+? WHERE tenant_id=? AND id=?',[$amount,$tid,$inv['id']]);fnJournal($tid,'SCHOLAR-'.$app['id'],'5400','1100',$amount,$inv['campus'],'Approved school scholarship fee waiver');fnRefresh($tid,(int)$inv['id']);$p['invoice_id']=(int)$inv['id'];q("UPDATE gv_applications SET status='applied',payload_json=? WHERE tenant_id=? AND id=?",[json_encode($p),$tid,$app['id']]);return 'Approved fee waiver applied once; no cash payment was created.';});}
if($a==='evidence'){ix_need($u,'accreditation_manager');$p=['authority'=>op_text('authority',180,true),'reference'=>op_text('reference',300,true),'expires_on'=>op_date(op_text('expires_on',10,true)),'summary'=>op_text('summary',2000,true)];$file=$_FILES['evidence_file']??null;if($file&&($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){if($file['error']!==UPLOAD_ERR_OK||$file['size']>3145728||!is_uploaded_file($file['tmp_name']))throw new RuntimeException('Upload PDF, JPEG or PNG evidence up to 3 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!in_array($mime,['application/pdf','image/png','image/jpeg'],true))throw new RuntimeException('Unsupported evidence format.');$p['mime']=$mime;$p['file_base64']=base64_encode(file_get_contents($file['tmp_name']));}gv_insert($u,'evidence',op_text('title',180,true),$p);return 'Private evidence registered for independent verification; no public upload URL created.';}
if($a==='deadline'){ix_need($u,'accreditation_manager');$owner=ix_fresh($tid,op_id('owner_id'));gv_insert($u,'deadlines',op_text('title',180,true),['due_on'=>op_date(op_text('due_on',10,true)),'authority'=>op_text('authority',180,true),'reference'=>op_text('reference',300,true),'owner_id'=>(int)$owner['id']],'open');return 'Inspection/compliance deadline assigned.';}
if($a==='complete_deadline'){ix_need($u,'accreditation_manager');$d=ix_own('gv_deadlines',$u,op_id('deadline_id'));$e=ix_own('gv_evidence',$u,op_id('evidence_id'));$ep=json_decode($e['payload_json'],true);if($e['status']!=='approved'||$ep['expires_on']<date('Y-m-d'))throw new RuntimeException('Current independently verified evidence required.');$p=json_decode($d['payload_json'],true);$p['evidence_id']=(int)$e['id'];q("UPDATE gv_deadlines SET status='completed',payload_json=?,reviewed_by=?,review_note=? WHERE tenant_id=? AND id=?",[json_encode($p),$uid,op_text('review_note',1000,true),$tid,$d['id']]);return 'Deadline completion linked to verified evidence; legal compliance is not automatically certified.';}
if($a==='processing'){ix_need($u,'privacy_officer');gv_insert($u,'processing',op_text('title',180,true),['purpose'=>op_text('purpose',2000,true),'lawful_basis'=>op_text('lawful_basis',500,true),'children'=>isset($_POST['children']),'retention_days'=>sv_qty('retention_days',36500),'processors_transfers'=>op_text('processors_transfers',2000,true),'dpia_reference'=>op_text('dpia_reference',500,true)]);return 'NDPA processing register entry awaiting independent privacy review; obtain qualified legal assessment.';}
if($a==='rights'){if(!in_array($u['role'],['parent','student','teacher','staff','school_admin'],true))throw new RuntimeException('School account required.');$sid=op_id('student_id',false);if($sid)op_child($u,$sid);gv_insert($u,'requests','Data subject request',['student_id'=>$sid,'type'=>sv_enum('type',['access','correction','erasure','restriction']),'reason'=>op_text('reason',2000,true),'identity_verified'=>false],'pending');return 'Private data rights request received; no record deletion or automatic legal decision performed.';}
if($a==='rights_review'){ix_need($u,'privacy_officer');$r=ix_own('gv_requests',$u,op_id('request_id'));if((int)$r['created_by']===$uid||$r['status']!=='pending'||op_text('identity_checked',10)!=='yes')throw new RuntimeException('Different privacy reviewer must verify requester identity and authority.');$p=json_decode($r['payload_json'],true);$p['identity_verified']=true;$p['response']=op_text('response',2000,true);$status=sv_enum('decision',['approved','rejected']);q('UPDATE gv_requests SET payload_json=?,status=?,reviewed_by=?,review_note=? WHERE tenant_id=? AND id=?',[json_encode($p),$status,$uid,$p['response'],$tid,$r['id']]);return 'Reviewed rights response recorded. Erasure/correction actions require the school’s separately reviewed record-specific procedure.';}
if($a==='group'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');q('INSERT INTO gv_groups(tenant_id,name,created_by) VALUES(?,?,?)',[$tid,op_text('name',180,true),$uid]);$id=(int)$GLOBALS['pdo']->lastInsertId();q("INSERT INTO gv_members(group_id,tenant_id,status,shares_json,approved_by) VALUES(?,?,'approved','[]',?)",[$id,$tid,$uid]);return 'School group #'.$id.' created. Each school must explicitly consent to aggregate sharing.';}
if($a==='invite'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');$group=ix_own('gv_groups',$u,op_id('group_id'));$other=op_id('school_id');if(!g('SELECT id FROM tenants WHERE id=?',[$other]))throw new RuntimeException('School unavailable.');q("INSERT INTO gv_members(group_id,tenant_id,status,shares_json) VALUES(?,?,'invited','[]') ON DUPLICATE KEY UPDATE group_id=VALUES(group_id)",[$group['id'],$other]);return 'Group invitation recorded; no school data shared.';}
if($a==='sharing'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');$id=op_id('group_id');if(!g('SELECT id FROM gv_members WHERE group_id=? AND tenant_id=?',[$id,$tid]))throw new RuntimeException('Group invitation unavailable.');$share=op_text('shares',500,true);$scopes=$share==='[]'?[]:gv_scopes($share);$status=sv_enum('decision',['approved','revoked']);q('UPDATE gv_members SET status=?,shares_json=?,approved_by=? WHERE group_id=? AND tenant_id=?',[$status,json_encode($scopes),$uid,$id,$tid]);return 'School sharing consent updated; revocation immediately blocks subsequent group requests.';}
if($a==='group_user'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');$id=op_id('group_id');gv_group_access($u,$id);$target=ix_fresh($tid,op_id('user_id'));ix_need($target,'group_analyst');if(sv_enum('decision',['grant','revoke'])==='grant')q('INSERT IGNORE INTO gv_group_users(tenant_id,group_id,user_id) VALUES(?,?,?)',[$tid,$id,$target['id']]);else q('DELETE FROM gv_group_users WHERE tenant_id=? AND group_id=? AND user_id=?',[$tid,$id,$target['id']]);return 'School group analyst grant updated.';}
if($a==='policy'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');$group=ix_own('gv_groups',$u,op_id('group_id'));gv_insert($u,'policies',op_text('title',180,true),['group_id'=>(int)$group['id'],'body'=>op_text('body',10000,true)]);return 'Headquarters policy draft created for independent review and local school adoption.';}
if($a==='adopt'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');$p=q("SELECT * FROM gv_policies WHERE id=? AND status='approved'",[op_id('policy_id')])->fetch();if(!$p)throw new RuntimeException('Approved policy unavailable.');$data=json_decode($p['payload_json'],true);gv_group_access($u,(int)$data['group_id']);q('INSERT INTO gv_adoptions(tenant_id,policy_id,reviewed_by,note) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE reviewed_by=VALUES(reviewed_by),note=VALUES(note)',[$tid,$p['id'],$uid,op_text('note',1000,true)]);return 'Policy adoption recorded; local settings were not overwritten.';}
if($a==='plugin'){ix_need($u,'integration_manager');$version=op_text('version',40,true);if(!preg_match('/^\d+\.\d+\.\d+$/D',$version))throw new RuntimeException('Use semantic version x.y.z.');$scopes=gv_scopes(op_text('scopes',500,true));foreach($scopes as $scope)rp_require($u,$scope);q('INSERT INTO gv_plugins(tenant_id,name,version,scopes_json,endpoint,created_by) VALUES(?,?,?,?,?,?)',[$tid,op_text('name',180,true),$version,json_encode($scopes),sv_https(op_text('endpoint',1200,true)),$uid]);return 'Declarative integration submitted for independent approval. No PHP uploads, remote code execution or outbound callback was enabled.';}
if($a==='approve_plugin'){ix_need($u,'integration_manager');$p=ix_own('gv_plugins',$u,op_id('plugin_id'));if($p['status']!=='draft'||(int)$p['created_by']===$uid)throw new RuntimeException('Different integration reviewer required.');foreach(json_decode($p['scopes_json'],true) as $scope)rp_require($u,$scope);q("UPDATE gv_plugins SET status='approved',approved_by=? WHERE tenant_id=? AND id=?",[$uid,$tid,$p['id']]);return 'Read-only API v1 integration approved.';}
if($a==='token'){ix_need($u,'integration_manager');$p=ix_own('gv_plugins',$u,op_id('plugin_id'));if($p['status']!=='approved')throw new RuntimeException('Approved integration required.');foreach(json_decode($p['scopes_json'],true) as $scope)rp_require($u,$scope);$token=bin2hex(random_bytes(32));$days=sv_qty('days',90);q('INSERT INTO gv_api_tokens(tenant_id,plugin_id,owner_id,token_hash,expires_at) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL ? DAY))',[$tid,$p['id'],$uid,hash('sha256',$token),$days]);$_SESSION['gv_token']=$token;return 'Expiring aggregate API token created. Copy it once and store securely; do not put tokens in URLs.';}
if($a==='revoke'){ix_need($u,'integration_manager');$token=ix_own('gv_api_tokens',$u,op_id('token_id'));if((int)$token['owner_id']!==$uid&&$u['role']!=='school_admin')throw new RuntimeException('Only token owner or school administrator may revoke.');q('UPDATE gv_api_tokens SET active=0 WHERE tenant_id=? AND id=?',[$tid,$token['id']]);return 'Integration token revoked.';}throw new RuntimeException('Unsupported governance action.');}
function gv_rows(array $u,string $kind,bool $publicApproved=false):array{$cap=ix_can($u,gv_cap($kind));$where=$cap?'':($publicApproved?" AND status='approved'":' AND created_by='.(int)$u['id']);$rows=q("SELECT id,title,payload_json,status,created_by,reviewed_by,review_note FROM gv_$kind WHERE tenant_id=?$where ORDER BY id DESC LIMIT 100",[$u['tenant_id']])->fetchAll();foreach($rows as &$r){$p=json_decode($r['payload_json'],true);unset($p['file_base64']);$r['payload_json']=json_encode($p,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}return $rows;}
function gv_render(array $u):void{$tid=(int)$u['tenant_id'];$tabs=['alumni'=>'Alumni & mentoring','scholarships'=>'Scholarships & fundraising','privacy'=>'Data protection','accreditation'=>'Accreditation','hq'=>'Group headquarters','plugins'=>'Approved integrations'];$view=ix_tabs('governance',$tabs,'alumni');op_card($tabs[$view]);$family=in_array($u['role'],['parent','student'],true);$children=sv_children($u);
if($view==='alumni'){op_table(gv_rows($u,'alumni',true),['ID','Adult alumnus','Profile','Status','Author','Verifier','Review']);if(ix_can($u,'alumni_manager'))ix_form('gv_alumni',['name'=>['Adult alumnus name','text'],'year'=>['Graduation year','text'],'profession'=>['Profession','text'],'topics'=>['Mentoring topics','textarea'],'adult_consent'=>['Adult consent and identity checked','check']],'Submit consented profile');if($family)ix_form('gv_mentoring',['student_id'=>['Student',$children],'alumni_id'=>['Approved alumnus ID','number'],'topic'=>['Mentoring topic','textarea']],'Request supervised mentoring');op_table(gv_rows($u,'mentoring'),['ID','Request','Details','Status','Requester','Reviewer','Review']);}
elseif($view==='scholarships'){foreach(['funds','scholarships'] as $kind){echo '<h3>'.e(ucfirst($kind)).'</h3>';op_table(gv_rows($u,$kind,true),['ID','Purpose','Budget and criteria','Status','Author','Reviewer','Review']);}if(ix_can($u,'alumni_manager'))foreach(['fund'=>'Fundraising purpose','scholarship'=>'Scholarship round'] as $action=>$label)ix_form('gv_'.$action,['title'=>[$label,'text'],'starts_on'=>['Opens','date'],'ends_on'=>['Closes','date'],'budget'=>['Goal / maximum budget (₦)','number'],'criteria'=>['Purpose, eligibility and review criteria','textarea']],'Submit '.$label);ix_form('gv_donation',['fund_id'=>['Approved fund ID','number'],'amount'=>['Bank donation declaration (₦)','number'],'note'=>['Bank transfer context; no credentials','textarea','',false]],'Declare donation for verification');if($family)ix_form('gv_application',['student_id'=>['Applicant',$children],'round_id'=>['Open approved round ID','number'],'amount'=>['Requested fee waiver (₦)','number'],'reason'=>['Eligibility and request','textarea']],'Submit application');foreach(['donations','applications'] as $kind)op_table(gv_rows($u,$kind),['ID','Request','Details','Status','Requester','Reviewer','Review']);if($u['role']==='school_admin')ix_form('gv_award',['application_id'=>['Approved application ID','number'],'invoice_id'=>['Linked student fee invoice ID','number']],'Apply approved scholarship fee waiver');echo '<p>Fundraising bank declarations require independent receipt verification. For online gifts, use the existing approved CMS payment workflow. Scholarship awards are budget-controlled fee waivers, not cash disbursements.</p>';}
elseif($view==='privacy'){echo '<p>Controls support the school’s NDPA 2023 programme; they do not certify legal compliance. Record children’s data purposes, lawful bases, retention, processors/transfers and DPIA references. Qualified school/privacy review remains necessary.</p>';if(ix_can($u,'privacy_officer')){ix_form('gv_processing',['title'=>['Processing activity','text'],'purpose'=>['Specific purpose','textarea'],'lawful_basis'=>['Documented lawful basis','textarea'],'children'=>['Includes children’s data','check'],'retention_days'=>['Retention days','number'],'processors_transfers'=>['Processors and international transfer arrangements','textarea'],'dpia_reference'=>['DPIA / child-data risk assessment reference','textarea']],'Submit processing register entry');op_table(gv_rows($u,'processing'),['ID','Activity','Register','Status','Author','Reviewer','Review']);ix_form('gv_rights_review',['request_id'=>['Pending rights request ID','number'],'identity_checked'=>['Requester identity and child authority verified','check'],'decision'=>['Decision',['approved'=>'Approved response','rejected'=>'Reasoned refusal']],'response'=>['Response, safeguards and manual record-specific follow-up','textarea']],'Record reviewed response');}ix_form('gv_rights',['student_id'=>['Own account: 0; linked child ID otherwise','number','0'],'type'=>['Request',['access'=>'Access','correction'=>'Correction','erasure'=>'Erasure review','restriction'=>'Restriction review']],'reason'=>['Request details','textarea']],'Submit private request');$rows=gv_rows($u,'requests');op_table($rows,['ID','Request','Details and response','Status','Requester','Reviewer','Review']);foreach($rows as $r)if((int)$r['created_by']===(int)$u['id']&&$r['status']==='approved')echo '<p><a href="?ix_rights='.(int)$r['id'].'">Download bounded approved access response #'.(int)$r['id'].'</a></p>';}
elseif($view==='accreditation'){ix_need($u,'accreditation_manager');ix_form('gv_evidence',['title'=>['Evidence title','text'],'authority'=>['Authority / state / inspection body','text'],'reference'=>['Requirement source reference','text'],'expires_on'=>['Valid until','date'],'summary'=>['Evidence summary; minimize child data','textarea'],'evidence_file'=>['Optional private PDF/JPEG/PNG up to 3 MB','file','',false]],'Submit private evidence');$rows=gv_rows($u,'evidence');op_table($rows,['ID','Evidence','Metadata','Status','Author','Verifier','Review']);foreach($rows as $r)echo '<a href="?ix_evidence='.(int)$r['id'].'">Private attachment #'.(int)$r['id'].'</a> ';ix_form('gv_deadline',['title'=>['Compliance / inspection deadline','text'],'due_on'=>['Due date','date'],'authority'=>['Authority / applicable state','text'],'reference'=>['Applicable rule source','text'],'owner_id'=>['Responsible school account ID','number']],'Assign deadline');op_table(gv_rows($u,'deadlines'),['ID','Deadline','Due date / owner / evidence','Status','Author','Completer','Review']);ix_form('gv_complete_deadline',['deadline_id'=>['Deadline ID','number'],'evidence_id'=>['Current independently verified evidence ID','number'],'review_note'=>['Completion review','textarea']],'Record evidence-backed completion');}
elseif($view==='hq'){ix_need($u,'group_analyst');$groups=q("SELECT g.id,g.name,m.status,m.shares_json FROM gv_members m JOIN gv_groups g ON g.id=m.group_id WHERE m.tenant_id=?",[$tid])->fetchAll();op_table($groups,['Group','Name','School consent','Shared aggregates']);if($u['role']==='school_admin'){ix_form('gv_group',['name'=>['School chain / group name','text']],'Create headquarters group');ix_form('gv_invite',['group_id'=>['Owned group ID','number'],'school_id'=>['School ID to invite','number']],'Invite school');ix_form('gv_sharing',['group_id'=>['Invited group ID','number'],'decision'=>['Consent',['approved'=>'Consent to listed aggregates','revoked'=>'Revoke all sharing']],'shares'=>['Dataset JSON ([] for none)','textarea','["executive","attendance"]']],'Save this school’s sharing consent');ix_form('gv_group_user',['group_id'=>['Group ID','number'],'user_id'=>['School analyst account ID','number'],'decision'=>['Access',['grant'=>'Grant','revoke'=>'Revoke']]],'Update explicit analyst grant');ix_form('gv_policy',['group_id'=>['Owned group ID','number'],'title'=>['Group policy title','text'],'body'=>['Policy text','textarea']],'Submit headquarters policy');ix_form('gv_adopt',['policy_id'=>['Approved group policy ID','number'],'note'=>['School review and implementation note','textarea']],'Record local policy adoption');}echo '<form method="get" class="op-form"><input type="hidden" name="s" value="intelligence"><input type="hidden" name="area" value="governance"><input type="hidden" name="view" value="hq">';op_field('group_id','Group ID','number');op_select('dataset','Approved shared dataset',array_combine(['executive','attendance','academics','enrolment','operations','finance'],['executive','attendance','academics','enrolment','operations','finance']));op_end('Load consented consolidated aggregates');if(isset($_GET['group_id'])){$rows=gv_group_report($u,(int)$_GET['group_id'],(string)($_GET['dataset']??'executive'),rp_filters($_GET));if($rows)op_table($rows,array_keys($rows[0]));}foreach($groups as $g){try{gv_group_access($u,(int)$g['id']);$members=q("SELECT p.* FROM gv_policies p JOIN gv_groups g ON g.tenant_id=p.tenant_id WHERE g.id=? AND p.status='approved'",[$g['id']])->fetchAll();foreach($members as $p)if((int)(json_decode($p['payload_json'],true)['group_id']??0)===(int)$g['id'])echo '<p>Policy #'.(int)$p['id'].' '.e($p['title']).': '.e(json_decode($p['payload_json'],true)['body']).'</p>';}catch(Throwable $ex){}}}
else{ix_need($u,'integration_manager');echo '<p>Approved declarative integrations use versioned, read-only aggregate APIs. No uploaded executable plugins or arbitrary SQL. GET index.php?ix_api=v1&amp;dataset=attendance with Authorization: Bearer TOKEN. Tokens expire, recheck current access, and allow 60 requests/minute. Keep responses private.</p>';ix_form('gv_plugin',['name'=>['Integration name','text'],'version'=>['Semantic version','text','1.0.0'],'scopes'=>['Aggregate dataset JSON','textarea','["attendance"]'],'endpoint'=>['Vendor HTTPS information URL (not fetched)','url']],'Submit integration');op_table(q('SELECT id,name,version,api_version,scopes_json,status,created_by,approved_by FROM gv_plugins WHERE tenant_id=?',[$tid])->fetchAll(),['ID','Name','Version','API','Scopes','Status','Author','Approver']);ix_form('gv_approve_plugin',['plugin_id'=>['Draft integration ID','number']],'Approve independently');ix_form('gv_token',['plugin_id'=>['Approved integration ID','number'],'days'=>['Expiry days (1–90)','number','30']],'Issue expiring token');if(isset($_SESSION['gv_token'])){echo '<p>Copy token once: <code>'.e($_SESSION['gv_token']).'</code></p>';unset($_SESSION['gv_token']);}op_table(q('SELECT id,plugin_id,owner_id,expires_at,active FROM gv_api_tokens WHERE tenant_id=? AND (owner_id=? OR ?=1)',[$tid,$u['id'],$u['role']==='school_admin'?1:0])->fetchAll(),['Token ID','Integration','Owner','Expires','Active']);ix_form('gv_revoke',['token_id'=>['Token ID','number']],'Revoke token');}
if(ix_can($u,'alumni_manager')||ix_can($u,'accreditation_manager')||ix_can($u,'privacy_officer')||ix_can($u,'group_analyst')){ix_form('gv_review',['kind'=>['Workflow',['alumni'=>'Adult alumni','mentoring'=>'Supervised mentoring','funds'=>'Fundraising purpose','donations'=>'Verified bank donation','scholarships'=>'Scholarship round','applications'=>'Scholarship application','evidence'=>'Accreditation evidence','processing'=>'Processing register','policies'=>'Headquarters policy']],'record_id'=>['Draft / pending record ID','number'],'decision'=>['Review',['approved'=>'Approve','rejected'=>'Reject']],'supervisor_id'=>['School employee supervisor ID (mentoring only)','number','',false],'bank_reference'=>['Verified bank receipt reference (donations only)','text','',false],'review_note'=>['Review evidence and rationale','textarea']],'Record independent review');}echo '</section>';}
